mapper.select:
SELECT

FROM t_sys_user_device a
WHERE a.id = #{id}

SELECT
FROM t_sys_user_device a
a.status = #{status}
AND ( a.user_id = #{query} OR a.device_id = #{query} OR a.location LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
OR a.user_name LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
OR a.device_name LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
OR a.ips LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
)
AND a.device_type = #{deviceType}
AND a.last_login_time BETWEEN #{beginLastLoginTime} AND #{endLastLoginTime}
AND a.last_login_time >= #{beginLastLoginTime}
AND a.last_login_time <= #{endLastLoginTime}
ORDER BY ${entityPage.orderBy} ${entityPage.order}
ORDER BY a.update_time DESC

SELECT
FROM t_sys_user_device a
a.status = #{status} AND a.user_id = #{userId}
AND a.device_id = #{deviceId}
AND ( a.location LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
OR a.device_name LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
OR a.ips LIKE
'%'||#{query}||'%' CONCAT('%', #{query}, '%') '%'||#{query}||'%' '%'+#{query}+'%'
)
ORDER BY ${entityPage.orderBy} ${entityPage.order}
ORDER BY a.update_time DESC

mapper.update:
UPDATE t_sys_user_device
SET status      = #{STATUS_DELETE},
    version     = version + 1,
    update_user = #{updateUser},
    update_time = #{updateTime}
WHERE id = #{id}
